const input = $input.first().json;

const hasExcel = input['Investment File Excel'] && input['Investment File Excel'].length > 0;
const hasPdf = input['IC Memo PDF'] && input['IC Memo PDF'].length > 0;

let mode = 'none';
if (hasExcel && hasPdf) mode = 'both';
else if (hasExcel) mode = 'excel';
else if (hasPdf) mode = 'pdf';

return [{
  json: {
    ...input,
    hasExcel: hasExcel,
    hasPdf: hasPdf,
    processingMode: mode,
    analyst: input['Analyst Name'],
    dealName: input['Deal Name']
  }
}];

const items = $input.all();
const metadata = $('Analyze Upload').first().json;

for (const item of items) {
  item.json.compute_marker = 1;
  item.json._analyst = metadata.analyst;
  item.json._deal_name = metadata.dealName;
  item.json._processed_at = new Date().toISOString();
}

return items;

const pdfText = $input.first().json.data || '';
const metadata = $('Analyze Upload').first().json;

// Extract investment amount using regex patterns
const patterns = [
  /\$([\d,]+(?:\.\d+)?)\s*(million|mn|m|billion|bn|b)?/i,
  /USD\s*([\d,]+(?:\.\d+)?)\s*(million|mn|m|billion|bn|b)?/i,
  /([\d,]+(?:\.\d+)?)\s*(million|mn|m|billion|bn|b)\s*(?:USD|dollars)/i,
  /investment\s*(?:amount|of|:)?\s*\$?([\d,]+(?:\.\d+)?)\s*(million|mn|m|billion|bn|b)?/i,
  /commitment\s*(?:of|:)?\s*\$?([\d,]+(?:\.\d+)?)\s*(million|mn|m|billion|bn|b)?/i
];

let amount = 0;
let currency = 'USD';

for (const pattern of patterns) {
  const match = pdfText.match(pattern);
  if (match) {
    amount = parseFloat(match[1].replace(/,/g, ''));
    const multiplier = (match[2] || '').toLowerCase();
    if (multiplier.startsWith('m')) amount *= 1000000;
    else if (multiplier.startsWith('b')) amount *= 1000000000;
    break;
  }
}

return [{
  json: {
    deal_name: metadata.dealName,
    analyst: metadata.analyst,
    investment_amount: amount,
    currency: currency,
    compute_marker: 1,
    source: 'IC_Memo_PDF',
    processed_at: new Date().toISOString()
  }
}];

const items = $input.all();
const metadata = $('Analyze Upload').first().json;

// Find PDF text data
let pdfText = '';
let excelRows = [];

for (const item of items) {
  if (item.json.data && typeof item.json.data === 'string') {
    pdfText = item.json.data;
  } else {
    excelRows.push(item.json);
  }
}

// Extract investment amount from PDF
const patterns = [
  /\$([\d,]+(?:\.\d+)?)\s*(million|mn|m|billion|bn|b)?/i,
  /([\d,]+(?:\.\d+)?)\s*(million|mn|m|billion|bn|b)\s*(?:USD|dollars)/i
];

let investmentAmount = 0;
for (const pattern of patterns) {
  const match = pdfText.match(pattern);
  if (match) {
    investmentAmount = parseFloat(match[1].replace(/,/g, ''));
    const mult = (match[2] || '').toLowerCase();
    if (mult.startsWith('m')) investmentAmount *= 1000000;
    else if (mult.startsWith('b')) investmentAmount *= 1000000000;
    break;
  }
}

// Add to all Excel rows
const result = excelRows.map(row => ({
  json: {
    ...row,
    compute_marker: 1,
    ic_memo_investment_amount: investmentAmount,
    _analyst: metadata.analyst,
    _deal_name: metadata.dealName,
    _processed_at: new Date().toISOString()
  }
}));

return result.length > 0 ? result : [{ json: { compute_marker: 1, ic_memo_investment_amount: investmentAmount, _analyst: metadata.analyst, _deal_name: metadata.dealName } }];
